ALTER TABLE public.subscriptions ADD COLUMN membership_kind text CHECK(membership_kind IN ('contractor','business'));
ALTER TABLE public.account_connection_invitations ADD COLUMN relationship_kind text NOT NULL DEFAULT 'business' CHECK(relationship_kind IN ('business','contractor_application','contractor_invitation'));
ALTER TABLE public.account_business_connections ADD COLUMN relationship_kind text NOT NULL DEFAULT 'business' CHECK(relationship_kind IN ('business','contractor'));
ALTER TABLE public.provider_network_profiles ADD COLUMN looking_for_work boolean NOT NULL DEFAULT false, ADD COLUMN seeking_contractors boolean NOT NULL DEFAULT false;
CREATE TABLE public.contractor_requirements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL CHECK(length(label) BETWEEN 2 AND 120),kind text NOT NULL CHECK(kind IN ('document','acknowledgment','expiration_date')),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=500),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.contractor_requirements TO authenticated; GRANT ALL ON public.contractor_requirements TO service_role;
ALTER TABLE public.contractor_requirements ENABLE ROW LEVEL SECURITY;
CREATE POLICY requirements_read ON public.contractor_requirements FOR SELECT TO authenticated USING(true);
CREATE TABLE public.contractor_requirement_responses(workspace_id uuid NOT NULL REFERENCES public.workspaces(id),requirement_id uuid NOT NULL REFERENCES public.contractor_requirements(id),credential_id uuid REFERENCES public.provider_credentials(id),acknowledged_at timestamptz,expires_on date,actor_id uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,requirement_id));
GRANT SELECT ON public.contractor_requirement_responses TO authenticated; GRANT ALL ON public.contractor_requirement_responses TO service_role;
ALTER TABLE public.contractor_requirement_responses ENABLE ROW LEVEL SECURITY;
CREATE POLICY requirement_response_read ON public.contractor_requirement_responses FOR SELECT TO authenticated USING(public.network_workspace_access(workspace_id,true));
CREATE TABLE public.contractor_safety_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),hold boolean NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 5 AND 500),actor_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.contractor_safety_events TO authenticated; GRANT ALL ON public.contractor_safety_events TO service_role;
ALTER TABLE public.contractor_safety_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY contractor_hold_read ON public.contractor_safety_events FOR SELECT TO authenticated USING(public.network_workspace_access(workspace_id,true) OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.contractor_new_workspace_subtype() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE chosen text; BEGIN IF NEW.account_type='provider' THEN SELECT raw_user_meta_data->>'provider_subtype' INTO chosen FROM auth.users WHERE id=NEW.created_by; IF chosen IN ('nemt_business','independent_contractor') THEN NEW.provider_subtype:=chosen;NEW.provider_subtype_selected_at:=now(); END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER contractor_registration_subtype BEFORE INSERT ON public.workspaces FOR EACH ROW EXECUTE FUNCTION public.contractor_new_workspace_subtype();
CREATE FUNCTION public.contractor_evidence_summary(_ws uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.workspaces;p public.provider_network_profiles;e boolean;v boolean;d boolean;x boolean;s boolean;a boolean;h boolean;r boolean;identity_ok boolean;reasons jsonb:='[]';eligible boolean; BEGIN SELECT * INTO w FROM public.workspaces WHERE id=_ws;SELECT * INTO p FROM public.provider_network_profiles WHERE workspace_id=_ws; IF w.id IS NULL OR w.provider_subtype<>'independent_contractor' THEN RETURN jsonb_build_object('eligible',false,'discoverable',false,'reasons',jsonb_build_array('Independent Contractor account required')); END IF;
SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN auth.users u ON u.id=m.user_id JOIN public.user_profiles up ON up.user_id=u.id WHERE m.workspace_id=_ws AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND u.email_confirmed_at IS NOT NULL AND up.status='active' AND NOT up.is_test_account AND up.deleted_at IS NULL),EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles up ON up.user_id=m.user_id WHERE m.workspace_id=_ws AND m.role='owner' AND m.removed_at IS NULL AND nullif(btrim(up.first_name),'') IS NOT NULL AND nullif(btrim(up.last_name),'') IS NOT NULL AND nullif(btrim(up.phone),'') IS NOT NULL) INTO e,identity_ok;
v:=(SELECT count(*)=1 FROM public.vehicles WHERE workspace_id=_ws AND status='active') AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=_ws AND v.status='active' AND v.vehicle_category='ambulatory' AND public.pass4p_vehicle_complete(v.id) AND v.service_capabilities=ARRAY['ambulatory']::text[] AND v.evidence_status IN ('under_review','satisfied'));
d:=NOT EXISTS(SELECT 1 FROM unnest(ARRAY['driver_license','auto_insurance','w9']) k WHERE NOT public.pass4p_document_present(_ws,k));x:=EXISTS(SELECT 1 FROM public.provider_credentials c WHERE c.workspace_id=_ws AND (c.required OR c.kind IN ('driver_license','auto_insurance','w9')) AND c.expires_at<current_date);
a:=coalesce(cardinality(p.counties)>0 AND cardinality(p.cities)>0 AND cardinality(p.zips)>0 AND p.service_radius_miles>0,false);
s:=EXISTS(SELECT 1 FROM public.subscriptions sub JOIN public.workspace_members m ON m.workspace_id=sub.workspace_id AND m.user_id=sub.user_id WHERE sub.workspace_id=_ws AND sub.membership_kind='contractor' AND sub.environment='live' AND sub.status='active' AND sub.membership_payment_state='succeeded' AND sub.membership_invoice_id IS NOT NULL AND sub.membership_currency='usd' AND sub.membership_paid_cents=2000 AND sub.current_period_end>now() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL);
h:=coalesce((SELECT hold FROM public.contractor_safety_events WHERE workspace_id=_ws ORDER BY created_at DESC,id DESC LIMIT 1),false);
r:=NOT EXISTS(SELECT 1 FROM public.contractor_requirements cr LEFT JOIN public.contractor_requirement_responses rr ON rr.requirement_id=cr.id AND rr.workspace_id=_ws LEFT JOIN public.provider_credentials c ON c.id=rr.credential_id AND c.workspace_id=_ws WHERE cr.active AND (rr.requirement_id IS NULL OR (cr.kind='acknowledgment' AND rr.acknowledged_at IS NULL) OR (cr.kind='expiration_date' AND (rr.expires_on IS NULL OR rr.expires_on<current_date)) OR (cr.kind='document' AND (c.id IS NULL OR NOT public.pass4p_document_present(_ws,c.kind)))));
IF h OR w.status<>'active' OR w.is_test_account THEN reasons:=reasons||jsonb_build_array('Restricted / safety hold');END IF;IF NOT e OR NOT identity_ok OR NOT v OR NOT a OR nullif(btrim(coalesce(p.hours,'')),'') IS NULL THEN reasons:=reasons||jsonb_build_array('Incomplete');END IF;IF x THEN reasons:=reasons||jsonb_build_array('Expired');END IF;IF NOT d OR NOT r THEN reasons:=reasons||jsonb_build_array('Evidence missing');ELSE reasons:=reasons||jsonb_build_array('Evidence present / unable to establish legal sufficiency');END IF;IF NOT s THEN reasons:=reasons||jsonb_build_array('Subscription inactive');END IF;IF NOT coalesce(p.visible,false) THEN reasons:=reasons||jsonb_build_array('Network visibility off');END IF;
eligible:=e AND identity_ok AND v AND a AND nullif(btrim(coalesce(p.hours,'')),'') IS NOT NULL AND d AND r AND NOT x AND s AND NOT h AND w.status='active' AND NOT w.is_test_account;IF eligible THEN reasons:=reasons||jsonb_build_array('Eligible for ambulatory opportunities');END IF;RETURN jsonb_build_object('eligible',eligible,'discoverable',eligible AND coalesce(p.visible,false),'reasons',reasons,'vehicle',v,'documents',d,'additional',r,'subscription',s,'email',e,'area',a,'availability',nullif(btrim(coalesce(p.hours,'')),'') IS NOT NULL);END $$;
REVOKE ALL ON FUNCTION public.contractor_evidence_summary(uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.contractor_evidence_summary(uuid) TO service_role;
CREATE FUNCTION public.contractor_eligibility(_ws uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.network_workspace_access(_ws,true) AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Account permission required';END IF;RETURN public.contractor_evidence_summary(_ws);END $$;
REVOKE ALL ON FUNCTION public.contractor_eligibility(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_eligibility(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pass4p_service_eligible(_ws uuid,_service text,_vehicle uuid DEFAULT NULL) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspaces w WHERE w.id=_ws AND w.status='active' AND NOT w.is_test_account AND ((w.provider_subtype='independent_contractor' AND _service='ambulatory' AND coalesce((public.contractor_evidence_summary(_ws)->>'eligible')::boolean,false) AND (_vehicle IS NULL OR EXISTS(SELECT 1 FROM public.vehicles WHERE id=_vehicle AND workspace_id=_ws AND status='active' AND vehicle_category='ambulatory'))) OR (w.provider_subtype='nemt_business' AND EXISTS(SELECT 1 FROM public.vehicles v WHERE v.workspace_id=_ws AND (_vehicle IS NULL OR v.id=_vehicle) AND public.pass4p_vehicle_complete(v.id) AND lower(_service)=ANY(v.service_capabilities))))) $$;
CREATE FUNCTION public.contractor_connected(_business uuid,_contractor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.account_business_connections c JOIN public.workspaces b ON b.id=_business JOIN public.workspaces k ON k.id=_contractor WHERE c.relationship_kind='contractor' AND c.active AND least(c.workspace_a,c.workspace_b)=least(_business,_contractor) AND greatest(c.workspace_a,c.workspace_b)=greatest(_business,_contractor) AND b.provider_subtype='nemt_business' AND k.provider_subtype='independent_contractor' AND b.status='active' AND k.status='active' AND NOT b.is_test_account AND NOT k.is_test_account) $$;
CREATE FUNCTION public.contractor_offer_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions;BEGIN IF EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.provider_workspace_id AND provider_subtype='independent_contractor') THEN SELECT * INTO d FROM public.trip_distributions WHERE id=NEW.distribution_id;IF d.capability<>'ambulatory' OR NOT public.contractor_connected(d.source_workspace_id,NEW.provider_workspace_id) OR NOT public.pass4p_service_eligible(NEW.provider_workspace_id,'ambulatory') THEN RAISE EXCEPTION 'Active contractor relationship and ambulatory eligibility required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_controlled_offer BEFORE INSERT OR UPDATE ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.contractor_offer_guard();
CREATE FUNCTION public.contractor_distribution_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.selected_workspace_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.workspaces WHERE id=NEW.selected_workspace_id AND provider_subtype='independent_contractor') AND (NEW.capability<>'ambulatory' OR NOT public.contractor_connected(NEW.source_workspace_id,NEW.selected_workspace_id) OR NOT public.pass4p_service_eligible(NEW.selected_workspace_id,'ambulatory')) THEN RAISE EXCEPTION 'Contractor relationship or eligibility unavailable';END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_selection_guard BEFORE INSERT OR UPDATE OF selected_workspace_id,capability ON public.trip_distributions FOR EACH ROW EXECUTE FUNCTION public.contractor_distribution_guard();
CREATE FUNCTION public.contractor_network_directory() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('workspace_id',w.id,'business_name',w.display_name,'mfn_id',w.mfn_id,'provider_subtype',w.provider_subtype,'counties',p.counties,'cities',p.cities,'zips',p.zips,'hours',p.hours,'service_types',CASE WHEN w.provider_subtype='independent_contractor' THEN ARRAY['ambulatory']::text[] ELSE p.service_types END,'service_radius_miles',p.service_radius_miles,'public_center_lat',p.public_center_lat,'public_center_lng',p.public_center_lng,'vehicle_category',CASE WHEN w.provider_subtype='independent_contractor' THEN 'Standard ambulatory vehicle' ELSE 'NEMT business fleet' END,'looking_for_work',p.looking_for_work,'seeking_contractors',p.seeking_contractors,'evidence_language',CASE WHEN w.provider_subtype='independent_contractor' THEN 'Current platform evidence; legal sufficiency not established' ELSE 'Eligible NEMT business' END)),'[]'::jsonb) FROM public.workspaces w JOIN public.provider_network_profiles p ON p.workspace_id=w.id WHERE auth.uid() IS NOT NULL AND w.account_type='provider' AND w.status='active' AND NOT w.is_test_account AND p.visible AND EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles up ON up.user_id=m.user_id WHERE m.workspace_id=w.id AND m.role='owner' AND m.removed_at IS NULL AND up.status='active' AND NOT up.is_test_account AND up.deleted_at IS NULL) AND ((w.provider_subtype='independent_contractor' AND (public.contractor_evidence_summary(w.id)->>'discoverable')::boolean) OR (w.provider_subtype='nemt_business' AND w.provider_verified AND p.seeking_contractors AND EXISTS(SELECT 1 FROM public.search_business_identities('signed_in','') bi WHERE bi.workspace_id=w.id))) $$;
REVOKE ALL ON FUNCTION public.contractor_network_directory() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_network_directory() TO authenticated,service_role;
CREATE FUNCTION public.contractor_set_listing(_ws uuid,_visible boolean,_looking boolean,_seeking boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.workspaces;BEGIN IF NOT public.network_workspace_access(_ws,true) THEN RAISE EXCEPTION 'Provider manager required';END IF;SELECT * INTO w FROM public.workspaces WHERE id=_ws;IF w.account_type<>'provider' OR w.is_test_account OR w.status<>'active' OR (w.provider_subtype='independent_contractor' AND _seeking) OR (w.provider_subtype='nemt_business' AND _looking) THEN RAISE EXCEPTION 'Invalid listing';END IF;IF w.provider_subtype='independent_contractor' AND _visible AND NOT (public.contractor_evidence_summary(_ws)->>'eligible')::boolean THEN RAISE EXCEPTION 'Complete evidence and active subscription before visibility';END IF;UPDATE public.provider_network_profiles SET visible=_visible,looking_for_work=_looking,seeking_contractors=_seeking WHERE workspace_id=_ws;IF NOT FOUND THEN RAISE EXCEPTION 'Save service profile first';END IF;END $$;
REVOKE ALL ON FUNCTION public.contractor_set_listing(uuid,boolean,boolean,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_set_listing(uuid,boolean,boolean,boolean) TO authenticated,service_role;
CREATE FUNCTION public.contractor_relationship_action(_ws uuid,_target uuid,_action text,_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a public.workspaces;b public.workspaces;i public.account_connection_invitations;rid uuid;uid uuid:=auth.uid();BEGIN IF NOT public.network_workspace_access(_ws,true) OR NOT public.can_access_workspace_messages(_ws) THEN RAISE EXCEPTION 'Provider manager and messaging permission required';END IF;SELECT * INTO a FROM public.workspaces WHERE id=_ws;IF a.is_test_account OR a.account_type<>'provider' THEN RAISE EXCEPTION 'Provider required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(least(_ws,_target)::text||greatest(_ws,_target)::text,0));SELECT * INTO b FROM public.workspaces WHERE id=_target;IF b.id IS NULL OR b.is_test_account OR b.status<>'active' OR b.account_type<>'provider' OR b.provider_subtype=a.provider_subtype THEN RAISE EXCEPTION 'Opposite eligible provider subtype required';END IF;
IF _action='request' THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(public.contractor_network_directory()) x WHERE x->>'workspace_id'=_target::text) THEN RAISE EXCEPTION 'Provider not discoverable';END IF;IF EXISTS(SELECT 1 FROM public.account_business_connections c WHERE c.active AND c.relationship_kind='contractor' AND least(c.workspace_a,c.workspace_b)=least(_ws,_target) AND greatest(c.workspace_a,c.workspace_b)=greatest(_ws,_target)) THEN RAISE EXCEPTION 'Already connected';END IF;SELECT id INTO rid FROM public.account_connection_invitations WHERE relationship_kind IN ('contractor_application','contractor_invitation') AND status='pending' AND expires_at>now() AND least(inviter_workspace_id,recipient_workspace_id)=least(_ws,_target) AND greatest(inviter_workspace_id,recipient_workspace_id)=greatest(_ws,_target) LIMIT 1;IF rid IS NOT NULL THEN RETURN rid;END IF;INSERT INTO public.account_connection_invitations(inviter_workspace_id,recipient_workspace_id,recipient_email,intended_type,status,token_hash,expires_at,created_by,person_mfn_id,workspace_mfn_id,relationship_kind,delivery_status) VALUES(_ws,_target,'','provider','pending',encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'),now()+interval '30 days',uid,(SELECT mfn_id FROM public.user_profiles WHERE user_id=uid),a.mfn_id,CASE WHEN a.provider_subtype='independent_contractor' THEN 'contractor_application' ELSE 'contractor_invitation' END,'not_requested') RETURNING id INTO rid;
ELSIF _action IN ('accept','decline') THEN SELECT * INTO i FROM public.account_connection_invitations WHERE id=_id FOR UPDATE;IF i.recipient_workspace_id IS DISTINCT FROM _ws OR i.inviter_workspace_id IS DISTINCT FROM _target OR i.relationship_kind NOT IN ('contractor_application','contractor_invitation') OR i.status<>'pending' OR i.expires_at<=now() THEN RAISE EXCEPTION 'Pending addressed invitation required';END IF;UPDATE public.account_connection_invitations SET status=CASE WHEN _action='accept' THEN 'accepted' ELSE 'declined' END,updated_at=now() WHERE id=i.id;rid:=i.id;IF _action='accept' THEN INSERT INTO public.account_business_connections(workspace_a,workspace_b,invitation_id,active,accepted_by,person_mfn_id,relationship_kind) VALUES(least(_ws,_target),greatest(_ws,_target),i.id,true,uid,(SELECT mfn_id FROM public.user_profiles WHERE user_id=uid),'contractor');END IF;
ELSIF _action='end' THEN UPDATE public.account_business_connections SET active=false,updated_at=now() WHERE id=_id AND relationship_kind='contractor' AND active AND least(workspace_a,workspace_b)=least(_ws,_target) AND greatest(workspace_a,workspace_b)=greatest(_ws,_target) RETURNING id INTO rid;IF rid IS NULL THEN RAISE EXCEPTION 'Active relationship required';END IF;ELSE RAISE EXCEPTION 'Invalid action';END IF;
INSERT INTO public.account_relationship_events(workspace_id,record_id,action,actor_id,person_mfn_id,workspace_mfn_id,details) VALUES(_ws,rid,'contractor_'||_action,uid,(SELECT mfn_id FROM public.user_profiles WHERE user_id=uid),a.mfn_id,jsonb_build_object('target',_target,'delivery','off'));RETURN rid;END $$;
REVOKE ALL ON FUNCTION public.contractor_relationship_action(uuid,uuid,text,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_relationship_action(uuid,uuid,text,uuid) TO authenticated,service_role;
CREATE POLICY contractor_invitation_read ON public.account_connection_invitations FOR SELECT TO authenticated USING(relationship_kind IN ('contractor_application','contractor_invitation') AND (public.network_workspace_access(inviter_workspace_id,true) OR public.network_workspace_access(recipient_workspace_id,true)));
CREATE FUNCTION public.contractor_requirement_save(_ws uuid,_req uuid,_credential uuid DEFAULT NULL,_ack boolean DEFAULT false,_expires date DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.contractor_requirements;BEGIN IF NOT public.network_workspace_access(_ws,true) OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=_ws AND user_id=auth.uid() AND role='owner' AND removed_at IS NULL) THEN RAISE EXCEPTION 'Owner required';END IF;SELECT * INTO r FROM public.contractor_requirements WHERE id=_req AND active;IF r.id IS NULL OR (r.kind='document' AND NOT EXISTS(SELECT 1 FROM public.provider_credentials WHERE id=_credential AND workspace_id=_ws AND provider_user_id=auth.uid())) OR (r.kind='acknowledgment' AND NOT _ack) OR (r.kind='expiration_date' AND (_expires IS NULL OR _expires<current_date)) THEN RAISE EXCEPTION 'Current requirement evidence required';END IF;INSERT INTO public.contractor_requirement_responses(workspace_id,requirement_id,credential_id,acknowledged_at,expires_on,actor_id) VALUES(_ws,_req,CASE WHEN r.kind='document' THEN _credential END,CASE WHEN r.kind='acknowledgment' THEN now() END,CASE WHEN r.kind='expiration_date' THEN _expires END,auth.uid()) ON CONFLICT(workspace_id,requirement_id) DO UPDATE SET credential_id=EXCLUDED.credential_id,acknowledged_at=EXCLUDED.acknowledged_at,expires_on=EXCLUDED.expires_on,actor_id=auth.uid(),updated_at=now();END $$;
REVOKE ALL ON FUNCTION public.contractor_requirement_save(uuid,uuid,uuid,boolean,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_requirement_save(uuid,uuid,uuid,boolean,date) TO authenticated,service_role;
CREATE FUNCTION public.contractor_admin_configuration(_action text,_details jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rid uuid;ws uuid;BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Master Admin required';END IF;IF _action='requirement' THEN rid:=coalesce((_details->>'id')::uuid,gen_random_uuid());INSERT INTO public.contractor_requirements(id,label,kind,notes,active) VALUES(rid,_details->>'label',_details->>'kind',coalesce(_details->>'notes',''),(_details->>'active')::boolean) ON CONFLICT(id) DO UPDATE SET label=EXCLUDED.label,kind=EXCLUDED.kind,notes=EXCLUDED.notes,active=EXCLUDED.active;ELSIF _action='hold' THEN ws:=(_details->>'workspaceId')::uuid;IF NOT EXISTS(SELECT 1 FROM public.workspaces WHERE id=ws AND provider_subtype='independent_contractor' AND NOT is_test_account) THEN RAISE EXCEPTION 'Contractor required';END IF;INSERT INTO public.contractor_safety_events(workspace_id,hold,reason,actor_id) VALUES(ws,(_details->>'hold')::boolean,_details->>'reason',auth.uid()) RETURNING id INTO rid;ELSE RAISE EXCEPTION 'Invalid configuration';END IF;INSERT INTO public.account_security_audit(user_id,sender_mfn_id,workspace_id,event_type,result) VALUES(auth.uid(),(SELECT mfn_id FROM public.user_profiles WHERE user_id=auth.uid()),ws,'contractor_'||_action,jsonb_build_object('record_id',rid,'action',_action));END $$;
REVOKE ALL ON FUNCTION public.contractor_admin_configuration(text,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_admin_configuration(text,jsonb) TO authenticated,service_role;